"""Data model for orchard blocks and trees."""

from dataclasses import dataclass, field
from typing import List

HECTARES_PER_ACRE = 0.404686


@dataclass
class Block:
    name: str
    variety: str
    tree_count: int
    area_acres: float
    capacitance_raw: float
    watermark_raw: float
    avg_fruit_mass_g: float

    @property
    def area_hectares(self) -> float:
        return self.area_acres * HECTARES_PER_ACRE


@dataclass
class Orchard:
    name: str
    blocks: List[Block] = field(default_factory=list)

    def total_trees(self) -> int:
        return sum(b.tree_count for b in self.blocks)
